/// Elevation shadows, one instance per reading theme.
///
/// CSS draws a blur of B as a Gaussian with sigma B / 2;
/// Flutter's BoxShadow turns blurRadius r into sigma
/// r * 0.57735 + 0.5. Each blurRadius is therefore
/// (B / 2 - 0.5) / 0.57735, so the shadows match the identity.
final class AppShadows extends ThemeExtension<AppShadows> {
  const AppShadows({required this.shadowCard, required this.shadowSheet});

  static const AppShadows paper = AppShadows(
    shadowCard: [
      BoxShadow(
        color: Color.from(
          alpha: 0.1,
          red: 7 / 255,
          green: 46 / 255,
          blue: 43 / 255,
        ),
        offset: Offset(0, 2),
        blurRadius: (8 / 2 - 0.5) / 0.57735,
      ),
    ],
    shadowSheet: [
      BoxShadow(
        color: Color.from(
          alpha: 0.2,
          red: 7 / 255,
          green: 46 / 255,
          blue: 43 / 255,
        ),
        offset: Offset(0, 12),
        blurRadius: (28 / 2 - 0.5) / 0.57735,
      ),
    ],
  );

  static const AppShadows night = AppShadows(
    shadowCard: [
      BoxShadow(
        color: Color.from(
          alpha: 0.35,
          red: 0 / 255,
          green: 0 / 255,
          blue: 0 / 255,
        ),
        offset: Offset(0, 2),
        blurRadius: (8 / 2 - 0.5) / 0.57735,
      ),
    ],
    shadowSheet: [
      BoxShadow(
